 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = {v: [(r, c) for r in range(h) for c in range(w) if grid[r][c] == v]
              for v in (1, 2, 3, 6)}

    # Connect 6 to 3 with a straight 5-segment. Connect 3 to 1 in the
    # diagonal direction; these are the two patterns shown by the examples.
    for a, b in ((6, 3), (3, 1)):
        if len(points[a]) != 1 or len(points[b]) != 1:
            continue
        (r1, c1), (r2, c2) = points[a][0], points[b][0]
        dr = (r2 > r1) - (r2 < r1)
        dc = (c2 > c1) - (c2 < c1)
        if dr == 0 or dc == 0 or abs(r2 - r1) == abs(c2 - c1):
            r, c = r1 + dr, c1 + dc
            while (r, c) != (r2, c2):
                if out[r][c] == 0:
                    out[r][c] = 5
                r += dr
                c += dc

    # The 1/2 pair makes the same diagonal/horizontal connecting segment.
    if len(points[1]) == 1 and len(points[2]) == 1:
        (r1, c1), (r2, c2) = points[1][0], points[2][0]
        dr = (r2 > r1) - (r2 < r1)
        dc = (c2 > c1) - (c2 < c1)
        if dr == 0 or dc == 0 or abs(r2 - r1) == abs(c2 - c1):
            r, c = r1 + dr, c1 + dc
            while (r, c) != (r2, c2):
                if out[r][c] == 0:
                    out[r][c] = 5
                r += dr
                c += dc

    return out
