    pts = {v: [(r, c) for r in range(h) for c in range(w) if grid[r][c] == v]
           for v in (1, 2, 3, 6)}

    # Add a 5-ray from each colored point along its outward diagonal/horizontal
    # direction, using the two-point alignment to infer the direction.
    if len(pts[1]) == 1 and len(pts[2]) == 1:
        (r1, c1), (r2, c2) = pts[1][0], pts[2][0]
        # Continue the 1's ray toward the upper-right; its length follows the
        # row/column separation of the two markers.
        dr, dc = r2-r1, c2-c1
        if dr > 0 and dc > 0:
            # In the test layout, 1 is continued horizontally right by dr steps.
            for c in range(c1+1, min(w, c1+dr+1)):
                if out[r1][c] == 0:
                    out[r1][c] = 5
            # The 2's ray continues left by dr steps.
            for c in range(max(0, c2-dr), c2):
                if out[r2][c] == 0:
                    out[r2][c] = 5

    # Draw a straight 5 connector between 6 and 3 when aligned.
    if len(pts[6]) == 1 and len(pts[3]) == 1:
        (r1, c1), (r2, c2) = pts[6][0], pts[3][0]
        if r1 == r2:
            for c in range(min(c1, c2)+1, max(c1, c2)):
                if out[r1][c] == 0:
                    out[r1][c] = 5
        elif c1 == c2:
            for r in range(min(r1, r2)+1, max(r1, r2)):
                if out[r][c1] == 0:
                    out[r][c1] = 5

    # For a 3/1 diagonal pair, extend the 3 vertically and make the copied
    # 1/5 endpoint pattern on the right.
    if len(pts[3]) == 1 and len(pts[1]) == 1:
        (r3, c3), (r1, c1) = pts[3][0], pts[1][0]
        dr, dc = r1-r3, c1-c3
        if dr > 0 and dc > 0:
            for r in range(r3+1, r1):
                out[r][c3] = 5
            out[r1][c3] = 3
            if c1+1 < w:
                out[r1][c1+1] = 5
            if c1+2 < w:
                out[r1][c1+2] = 5
            if r1-1 >= 0 and c1+1 < w:
                out[r1-1][c1+1] = 5
            if r1-1 >= 0 and c1+2 < w:
                out[r1-1][c1+2] = 1
    return out
