from pathlib import Path
p=Path('programs/task-05d6f3eb.py')
s='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    pos = {v: [(r, c) for r in range(h) for c in range(w) if grid[r][c] == v]
           for v in (1, 2, 3, 6)}

    # The input's markers each produce a short colored motif.
    # 1: two 5s to the right and a copied 1 two columns right, one row up.
    for r, c in pos[1]:
        for dc in (1, 2):
            if c + dc < w:
                out[r][c + dc] = 5
        if r > 0 and c + 2 < w:
            out[r - 1][c + 2] = 1

    # 2: leftward repeated-2 motif. When a 3 is diagonally above-left,
    # the central 5 is replaced by 4 and a 4-color diagonal descends from it.
    special_2 = any(r3 < r2 and c3 < c2
                    for r3, c3 in pos[3] for r2, c2 in pos[2])
    for r, c in pos[2]:
        if c - 4 >= 0:
            out[r][c - 4] = 2
        for dc in (-3, -2, -1):
            if c + dc >= 0:
                out[r][c + dc] = 4 if special_2 and dc == -2 else 5
        if special_2:
            rr, cc = r + 1, c - 3
            while rr < h and cc >= 0:
                out[rr][cc] = 4
                rr += 1
                cc -= 1

    # A 3 paired with a lower-right 2 extends downward to the 2's row.
    for r, c in pos[3]:
        targets = [(rr, cc) for rr, cc in pos[2] if rr > r and cc > c]
        if targets:
            rr, cc = min(targets, key=lambda q: q[0] - r)
            for y in range(r + 1, rr):
                out[y][c] = 5
